import {selectedBranding} from './branding.js?v=receipt-checked-81';
import {businessDefaults} from './invoices.js?v=receipt-checked-81';
export const corePaymentStages=['Booking Amount','On Event','After Event','Delivery','Album Printing'];
export function stageName(value){const name=String(value||'Other').trim();return ({booking:'Booking Amount','booking amount':'Booking Amount','on-event':'On Event','on event':'On Event','after event':'After Event','album printing':'Album Printing',delivery:'Delivery'})[name.toLowerCase()]||name;}
export function stageSummary(data,clientId){const payments=data.payments.filter(p=>p.client===clientId),plans=data.settings.paymentStagePlans?.[clientId]||{},names=[...new Set([...corePaymentStages,...Object.keys(plans),...payments.map(p=>stageName(p.stage))])];return names.map(name=>{const rows=payments.filter(p=>stageName(p.stage)===name),received=rows.reduce((n,p)=>n+p.amount,0),target=plans[name];return {name,rows,received,target,pending:target===undefined?null:Math.max(0,target-received),status:target===undefined?(received?'Received':'Not set'):target===0&&!received?'Not required':received>=target?'Paid':received?'Partially paid':'Pending'};});}
export function paymentDocumentDraft(store,paymentId,kind='receipt'){if(!['receipt','stage-invoice'].includes(kind))throw Error('Choose invoice or receipt');const payment=store.data.payments.find(p=>p.id===paymentId);if(!payment)throw Error('Payment not found');const client=store.data.clients.find(c=>c.id===payment.client),booking=store.data.packages?.find(p=>p.id===payment.package);const branding=selectedBranding(store);return {companyId:store.companyId,theme:branding.theme,templateId:branding.templateId,documentKind:kind,paymentId,client:payment.client,package:payment.package||'',billTo:client.name,date:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),company:{...businessDefaults,...branding.business,company:branding.business.company||store.data.settings.company},payment:structuredClone(payment),stage:stageName(payment.stage),amount:payment.amount,quote:store.quote(payment.client),received:store.paid(payment.client),outstanding:store.balance(payment.client),bookingName:booking?.name||client.package||'Client booking',events:store.data.events.filter(e=>e.client===client.id&&(!payment.event||e.id===payment.event)).map(e=>({type:e.type,date:e.date,venue:e.venue})),notes:payment.notes||''};}
export function issuePaymentDocument(store,draft,save){const existing=(store.data.invoices||[]).find(i=>i.paymentId===draft.paymentId&&i.documentKind===draft.documentKind);if(existing)return existing;const current=paymentDocumentDraft(store,draft.paymentId,draft.documentKind);if(JSON.stringify(current.payment)!==JSON.stringify(draft.payment)||current.quote!==draft.quote||current.received!==draft.received)throw Error('Payments changed. Reopen the document preview.');return save(store,draft);}
